CREATE TYPE "EntityStatus" AS ENUM ('ACTIVE', 'INACTIVE', 'SUSPENDED');
CREATE TYPE "SystemRole" AS ENUM ('SYSTEM_ADMIN', 'ORGANIZATION_ADMIN', 'AIRPORT_ADMIN', 'USER');
CREATE TABLE "users" ("id" UUID NOT NULL, "name" VARCHAR(160) NOT NULL, "email" VARCHAR(254) NOT NULL, "password_hash" VARCHAR(255) NOT NULL, "status" "EntityStatus" NOT NULL DEFAULT 'ACTIVE', "mfa_enrolled_at" TIMESTAMPTZ(6), "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL, "deleted_at" TIMESTAMPTZ(6), CONSTRAINT "users_pkey" PRIMARY KEY ("id"));
CREATE TABLE "organizations" ("id" UUID NOT NULL, "legal_name" VARCHAR(200) NOT NULL, "trade_name" VARCHAR(200), "status" "EntityStatus" NOT NULL DEFAULT 'ACTIVE', "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL, "deleted_at" TIMESTAMPTZ(6), CONSTRAINT "organizations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "airports" ("id" UUID NOT NULL, "organization_id" UUID NOT NULL, "name" VARCHAR(200) NOT NULL, "icao_code" VARCHAR(4), "iata_code" VARCHAR(3), "city" VARCHAR(120) NOT NULL, "state" VARCHAR(2) NOT NULL, "country" VARCHAR(2) NOT NULL DEFAULT 'BR', "status" "EntityStatus" NOT NULL DEFAULT 'ACTIVE', "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL, "deleted_at" TIMESTAMPTZ(6), CONSTRAINT "airports_pkey" PRIMARY KEY ("id"));
CREATE TABLE "memberships" ("id" UUID NOT NULL, "user_id" UUID NOT NULL, "organization_id" UUID NOT NULL, "role" "SystemRole" NOT NULL DEFAULT 'USER', "status" "EntityStatus" NOT NULL DEFAULT 'ACTIVE', "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL, "deleted_at" TIMESTAMPTZ(6), CONSTRAINT "memberships_pkey" PRIMARY KEY ("id"));
CREATE TABLE "airport_accesses" ("id" UUID NOT NULL, "membership_id" UUID NOT NULL, "airport_id" UUID NOT NULL, "role" "SystemRole" NOT NULL DEFAULT 'USER', "status" "EntityStatus" NOT NULL DEFAULT 'ACTIVE', "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL, "deleted_at" TIMESTAMPTZ(6), CONSTRAINT "airport_accesses_pkey" PRIMARY KEY ("id"));
CREATE TABLE "sessions" ("id" UUID NOT NULL, "token_hash" CHAR(64) NOT NULL, "user_id" UUID NOT NULL, "active_organization_id" UUID, "active_airport_id" UUID, "expires_at" TIMESTAMPTZ(6) NOT NULL, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "last_seen_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "revoked_at" TIMESTAMPTZ(6), CONSTRAINT "sessions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "audit_logs" ("id" UUID NOT NULL, "timestamp" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "user_id" UUID, "organization_id" UUID, "airport_id" UUID, "action" VARCHAR(100) NOT NULL, "entity_type" VARCHAR(100) NOT NULL, "entity_id" VARCHAR(100), "previous_value" JSONB, "new_value" JSONB, "metadata" JSONB, CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "users_email_key" ON "users"("email"); CREATE UNIQUE INDEX "sessions_token_hash_key" ON "sessions"("token_hash");
CREATE UNIQUE INDEX "memberships_user_id_organization_id_key" ON "memberships"("user_id", "organization_id"); CREATE UNIQUE INDEX "airport_accesses_membership_id_airport_id_key" ON "airport_accesses"("membership_id", "airport_id");
CREATE UNIQUE INDEX "airports_organization_id_icao_code_key" ON "airports"("organization_id", "icao_code"); CREATE UNIQUE INDEX "airports_organization_id_iata_code_key" ON "airports"("organization_id", "iata_code");
CREATE INDEX "organizations_status_deleted_at_idx" ON "organizations"("status", "deleted_at"); CREATE INDEX "airports_organization_id_status_deleted_at_idx" ON "airports"("organization_id", "status", "deleted_at"); CREATE INDEX "memberships_organization_id_status_deleted_at_idx" ON "memberships"("organization_id", "status", "deleted_at"); CREATE INDEX "airport_accesses_airport_id_status_deleted_at_idx" ON "airport_accesses"("airport_id", "status", "deleted_at"); CREATE INDEX "sessions_user_id_expires_at_idx" ON "sessions"("user_id", "expires_at"); CREATE INDEX "audit_logs_organization_id_timestamp_idx" ON "audit_logs"("organization_id", "timestamp"); CREATE INDEX "audit_logs_airport_id_timestamp_idx" ON "audit_logs"("airport_id", "timestamp"); CREATE INDEX "audit_logs_entity_type_entity_id_idx" ON "audit_logs"("entity_type", "entity_id");
ALTER TABLE "airports" ADD CONSTRAINT "airports_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "memberships" ADD CONSTRAINT "memberships_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "memberships" ADD CONSTRAINT "memberships_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "airport_accesses" ADD CONSTRAINT "airport_accesses_membership_id_fkey" FOREIGN KEY ("membership_id") REFERENCES "memberships"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "airport_accesses" ADD CONSTRAINT "airport_accesses_airport_id_fkey" FOREIGN KEY ("airport_id") REFERENCES "airports"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "sessions" ADD CONSTRAINT "sessions_active_organization_id_fkey" FOREIGN KEY ("active_organization_id") REFERENCES "organizations"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "sessions" ADD CONSTRAINT "sessions_active_airport_id_fkey" FOREIGN KEY ("active_airport_id") REFERENCES "airports"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_airport_id_fkey" FOREIGN KEY ("airport_id") REFERENCES "airports"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
-- Audit records are append-only even for database roles that bypass the application.
CREATE OR REPLACE FUNCTION prevent_audit_log_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'audit_logs are append-only'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER audit_logs_append_only BEFORE UPDATE OR DELETE ON "audit_logs" FOR EACH ROW EXECUTE FUNCTION prevent_audit_log_mutation();
